def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        if coeff < 0:
            sign = '-'
        else:
            sign = '+'
        if abs(coeff) != 1 or degree == 0:
            coeff_str = str(abs(coeff))
        else:
            coeff_str = ''
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'
        terms.append(f'{sign}{coeff_str}{var_str}')
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i, c in enumerate(encoded):
        if c not in mapping:
            mapping[c] = original[i]

    # Check for contradictions in the mapping
    for c in encoded:
        if mapping[c] != original[encoded.index(c)]:
            return "Failed"

    # Decode the message using the mapping
    decoded = ""
    for c in message:
        if c in mapping:
            decoded += mapping[c]
        else:
            return "Failed"

    return decoded

def count_partitions(n, k, x):
    # Initialize a 2D array to store the results
    dp = [[0] * (k+1) for _ in range(n+1)]

    # Initialize the first row of the array
    for i in range(1, k+1):
        dp[0][i] = 1

    # Fill in the table
    for i in range(1, n+1):
        for j in range(1, k+1):
            for l in range(x, i+1):
                dp[i][j] += dp[i-l][j-1]

    # Return the last entry in the last row
    return dp[n][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == 1:
        return 1
    if last in memo:
        return memo[last]
    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)
    memo[last] = count
    return count

