def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num in [2, 3]:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    for i in range(5, int(num ** 0.5) + 1, 6):
        if num % i == 0 or num % (i + 2) == 0:
            return False
    return True

def generate_numbers(n, rules):
    queue = [n]
    visited = set()
    count = 0
    while queue:
        num = queue.pop(0)
        if num not in visited:
            visited.add(num)
            count += 1
            for rule in rules:
                new_num = apply_rule(num, rule)
                if new_num not in visited:
                    queue.append(new_num)
    return count

def apply_rule(num, rule):
