def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Populate the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # Case 1: Do not include the current item
            dp[i][j] = dp[i][j - 1]

            # Case 2: Include the current item
            if i - volumes[j - 1] >= 0:
                dp[i][j] = max(dp[i][j], dp[i - volumes[j - 1]][j - 1] + volumes[j - 1])

    # Return the minimum remaining space
    return V - dp[V][n]

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [[0] * (m+1) for _ in range(n+1)]
    dp[0][0] = 1
    for i in range(1, n+1):
        for j in range(m+1):
            for k in range(a[i-1]+1):
                if j >= k:
                    dp[i][j] += dp[i-1][j-k]
                    dp[i][j] %= MOD
    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    plaintext = ""
    for i in range(len(ciphertext)):
        plaintext += chr((ord(ciphertext[i]) - ord(key[i % len(key)]) + 26) % 26 + ord('A'))
    return plaintext

def mod_inverse(a, b):
    gcd, x, _ = egcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def egcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        gcd, x, y = egcd(b % a, a)
        return (gcd, y - (b // a) * x, x)

